if (session_status() !== PHP_SESSION_ACTIVE) session_start();
function h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function user(): ?array { return isset($_SESSION['user_id']) ? ['id'=>(int)$_SESSION['user_id'],'name'=>$_SESSION['full_name'] ?? $_SESSION['username'],'username'=>$_SESSION['username'],'role'=>$_SESSION['role']] : null; }
function require_role(array $roles): void { $u=user(); if (!$u || !in_array($u['role'],$roles,true)) { header('Location: '.(strpos($_SERVER['PHP_SELF'],'/admin/')!==false?'../':'').'login.php'); exit; } }
function page_start(string $title): void { $u=user(); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?> · MealDash</title><link rel="stylesheet" href="<?=strpos($_SERVER['PHP_SELF'],'/admin/')!==false?'../':''?>style.css"><style>
body{display:block;min-height:100vh;background:#f7f8fa;color:#20252b;font-family:Segoe UI,Arial,sans-serif}.nav{height:auto;min-height:64px;display:flex;justify-content:space-between;align-items:center;padding:12px max(5vw,20px);background:#fff;border-bottom:1px solid #e8eaf0}.nav a{color:#29323d;text-decoration:none;margin:0 9px}.brand{font-weight:800;color:#ed6534!important;font-size:22px}.wrap{max-width:1120px;margin:32px auto;padding:0 20px}.hero{padding:40px;border-radius:18px;background:linear-gradient(120deg,#fff0e8,#fff);margin-bottom:24px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:18px}.card{background:white;padding:20px;border:1px solid #eceef1;border-radius:14px;box-shadow:0 4px 14px #1f293308}.card img{width:100%;height:150px;object-fit:cover;border-radius:10px}.pill{display:inline-block;background:#fff0e8;color:#ba4b20;border-radius:20px;padding:5px 10px;font-size:13px}.btn,button{display:inline-block;background:#ed6534;color:white!important;text-decoration:none;border:0;border-radius:8px;padding:10px 15px;cursor:pointer;font-weight:650}.btn.secondary{background:#344054}.row{display:flex;justify-content:space-between;align-items:center;gap:12px}.muted{color:#697586}.field{width:100%;box-sizing:border-box;padding:11px;border:1px solid #ccd2da;border-radius:8px;margin:6px 0 14px}table{width:100%;border-collapse:collapse;background:#fff}td,th{padding:12px;border-bottom:1px solid #eceef1;text-align:left}form.inline{display:inline}footer{padding:25px;text-align:center;color:#697586}@media(max-width:600px){.nav{align-items:flex-start;flex-direction:column;gap:8px}.hero{padding:25px}}
