function page_end(): void { ?></main><footer>MealDash · Local food ordering demo</footer></body></html><?php }
function flash(string $msg): void { $_SESSION['flash']=$msg; }
function take_flash(): ?string { $m=$_SESSION['flash']??null; unset($_SESSION['flash']); return $m; }
function csrf_field(): void { if(empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); echo '<input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'">'; }
function check_csrf(): void { if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){ http_response_code(400); exit('Invalid form token. Reload and try again.'); } }
